<?php $byCategory=$filters['brand']&&!$filters['category']&&!$filters['sub_category'];$sidebarRecords=$byCategory?$brandCategories:$brands;$sidebarKey=$byCategory?'category':'brand';?>
<aside class="catalog-sidebar" aria-label="Product filters"><div class="catalog-sidebar-section"><div class="catalog-sidebar-title"><?=text($byCategory?'categories':'brands')?></div><a class="catalog-category-link <?=!$filters[$sidebarKey]?'active':''?>" href="<?=e($filterUrl([$sidebarKey=>null,'sub_category'=>null]))?>"><span><i class="fa-solid fa-border-all"></i><?=text($byCategory?'all_categories':'all_brands')?></span></a><?php foreach($sidebarRecords as $record):?><a class="catalog-category-link <?=($filters[$sidebarKey]['id']??null)===$record['id']?'active':''?>" href="<?=e($filterUrl([$sidebarKey=>$byCategory?$record['title']:$record['id'],'sub_category'=>null]))?>"><span><i class="<?=e(($record['icon']??'')?:($byCategory?'fa-solid fa-layer-group':'fa-solid fa-tag'))?>"></i><?=e($record['title'])?></span></a><?php endforeach?><?php if(!$sidebarRecords):?><span class="catalog-sidebar-empty"><?=text('no_data')?></span><?php endif?></div></aside>
